    "age calculator": {title:"Age Calculator",fields:[["dob","Date of birth","date","2000-01-01"],["asof","Age on date","date",localDateString(new Date())]],calc:v=>{const a=new Date(v.dob+"T00:00:00"),b=new Date(v.asof+"T00:00:00");if(!Number.isFinite(a.getTime())||!Number.isFinite(b.getTime())||a>b)return [];let y=b.getFullYear()-a.getFullYear(),m=b.getMonth()-a.getMonth(),d=b.getDate()-a.getDate();if(d<0){m--;d+=new Date(b.getFullYear(),b.getMonth(),0).getDate()}if(m<0){y--;m+=12}return [["Age",y+" years, "+m+" months, "+d+" days"]];}},
    "electricity bill calculator": {title:"Electricity Bill Calculator",fields:[["units","Units consumed (kWh)","number",200],["rate","Rate per unit (₹)","number",7],["fixed","Fixed charges (₹)","number",100],["other","Other charges (₹)","number",0]],calc:v=>[["Energy charges",v.units*v.rate],["Estimated bill",v.units*v.rate+v.fixed+v.other]]},
