    "home loan amortization schedule calculator": {title:"Home Loan Amortization Schedule Calculator",fields:[["principal","Home loan amount (₹)","number",3000000],["rate","Annual interest rate (%)","number",8.5],["years","Loan tenure (years)","number",20]],calc:v=>{if(v.principal<=0||v.years<=0||v.years>50)return [];const n=Math.round(v.years*12),r=v.rate/1200,p=v.principal,emi=r===0?p/n:p*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1);let balance=p,totalInterest=0;const rows=[["Monthly EMI",emi],["Total interest",0],["Total repayment",0]];const schedule=[];for(let m=1;m<=n;m++){const interest=balance*r,principal=Math.min(balance,emi-interest);balance=Math.max(0,balance-principal);totalInterest+=interest;schedule.push(["Month "+m,"Principal ₹"+principal.toFixed(2)+" · Interest ₹"+interest.toFixed(2)+" · Balance ₹"+balance.toFixed(2)]);}rows[1][1]=totalInterest;rows[2][1]=p+totalInterest;return [...rows,...schedule];}},
    "loan comparison calculator": {title:"Loan Comparison Calculator",fields:[["principal","Loan amount (₹)","number",1000000],["rateA","Option A annual rate (%)","number",8.5],["yearsA","Option A tenure (years)","number",15],["rateB","Option B annual rate (%)","number",9],["yearsB","Option B tenure (years)","number",15]],calc:v=>{const calc=(rate,years)=>{const n=years*12,r=rate/1200,p=v.principal;if(n<=0||n>600)return null;const emi=r===0?p/n:p*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1);return {emi,total:emi*n,interest:emi*n-p}};const a=calc(v.rateA,v.yearsA),b=calc(v.rateB,v.yearsB);if(!a||!b||v.principal<=0)return [];return [["Option A monthly EMI",a.emi],["Option A total interest",a.interest],["Option A total repayment",a.total],["Option B monthly EMI",b.emi],["Option B total interest",b.interest],["Option B total repayment",b.total],["Difference in total interest (A − B)",a.interest-b.interest]];}},
