    "unit price comparison calculator": {title:"Unit Price Comparison Calculator",fields:[["priceA","Option A total price (₹)","number",180],["qtyA","Option A quantity","number",750],["priceB","Option B total price (₹)","number",220],["qtyB","Option B quantity","number",1000]],calc:v=>{if(v.qtyA<=0||v.qtyB<=0)return [];const a=v.priceA/v.qtyA,b=v.priceB/v.qtyB;return [["Option A price per unit",a],["Option B price per unit",b],["Lower unit price",a<=b?"Option A":"Option B"],["Difference per unit",Math.abs(a-b)]];}},
